        val root = gql(Queries.campaignDetails(prefs.userId.orEmpty(), id), useIntegrity = true)
        return root.optJSONObject("data")?.optJSONObject("user")?.optJSONObject("dropCampaign")?.let(::parseCampaign)
    }

