    suspend fun gameCampaigns(game: WatchedGame): List<InvCampaign> =
        dashboard(useIntegrity = true).campaigns.orEmpty()
            .filter { it.status == "ACTIVE" && game.matches(it.gameId, it.game) }
            .mapNotNull { campaignDetails(it.id) }

